import {App,Modal,Notice,Setting} from 'obsidian';
import {makeBackup,parseBackup} from './settings-backup';
interface Host{app:App;settings:any;restoreSettings(values:any):Promise<void>}
export class SettingsTransfer{
 private busy=false;
 constructor(private host:Host,private refresh:()=>void){}
 private error(message:string){const m=new Modal(this.host.app);m.setTitle('설정을 복원할 수 없습니다');m.contentEl.createEl('p',{text:message});m.contentEl.createEl('p',{text:'현재 설정과 캔버스 데이터는 변경하지 않았습니다.'});new Setting(m.contentEl).addButton(b=>b.setButtonText('닫기').onClick(()=>m.close()));m.open();}
 async backup(){if(this.busy)return;this.busy=true;try{const text=makeBackup(this.host.settings),remote=require('electron').remote;const result=await remote.dialog.showSaveDialog((remote.BrowserWindow.getFocusedWindow()||remote.getCurrentWindow()),{title:'Canvas Mindmap 설정 백업',defaultPath:'Canvas-Mindmap-설정.json',filters:[{name:'설정 백업 (JSON)',extensions:['json']}],properties:['showOverwriteConfirmation']});if(result.canceled||!result.filePath)return;await require('fs').promises.writeFile(result.filePath,text,'utf8');new Notice('설정을 백업했습니다.');}catch(error){console.error('Canvas Mindmap backup',error);new Notice('설정을 백업하지 못했습니다. 저장 위치와 파일 권한을 확인하세요.');}finally{this.busy=false;}}
 async restore(){if(this.busy)return;this.busy=true;try{const remote=require('electron').remote,result=await remote.dialog.showOpenDialog((remote.BrowserWindow.getFocusedWindow()||remote.getCurrentWindow()),{title:'Canvas Mindmap 설정 복원',filters:[{name:'설정 백업 (JSON)',extensions:['json']}],properties:['openFile']});if(result.canceled||!result.filePaths[0])return;const f=require('fs').promises;if((await f.stat(result.filePaths[0])).size>1024*1024)throw Error('백업 파일이 너무 큽니다.');const values=parseBackup(await f.readFile(result.filePaths[0],'utf8'));await this.confirm(values);}catch{this.error('백업 파일이 손상되었거나 지원하지 않는 형식입니다. 파일을 읽을 수 있는지도 확인하세요.');}finally{this.busy=false;}}
 private confirm(values:any){return new Promise<void>(resolve=>{const m=new Modal(this.host.app);let applying=false;m.setTitle('설정을 복원할까요?');m.contentEl.createEl('p',{text:'설정창의 설정값 전체를 선택한 백업의 값으로 교체합니다.'});m.contentEl.createEl('p',{text:'관리창 크기, Waypoint, 사용자 색상, 연결 출발점과 캔버스 내용은 그대로 유지됩니다.'});m.onClose=()=>resolve();new Setting(m.contentEl).addButton(b=>b.setButtonText('취소').onClick(()=>{if(!applying)m.close()})).addButton(b=>b.setButtonText('복원').setCta().onClick(async()=>{if(applying)return;applying=true;b.setDisabled(true);try{await this.host.restoreSettings(values);m.close();this.refresh();new Notice('설정을 복원했습니다.');}catch{m.close();this.error('설정을 저장하지 못해 복원을 중단했습니다.');}}));m.open();});}
}
